  async function mediaUrl(path){if(!path)return'';path+=(path.includes('?')?'&':'?')+'liveRevision='+encodeURIComponent(payload?.revision||0);if(objectUrls.has(path))return objectUrls.get(path);const generation=mediaGeneration;try{const blob=await apiMedia(path),url=URL.createObjectURL(blob);if(generation!==mediaGeneration||!modeActive){URL.revokeObjectURL(url);return''}objectUrls.set(path,url);return url}catch{return''}}
