  function previewMarkup(entryId){return (judgeFiles.get(entryId)||[]).map(item=>`<figure class="admin-live-upload-preview" data-upload-state="${escapeHtml(item.status)}">${item.url?`<img alt="Náhled ${escapeHtml(item.file.name)}" src="${escapeHtml(item.url)}">`:'<span>Náhled není dostupný</span>'}<figcaption><b>${escapeHtml(item.file.name)}</b><small>${escapeHtml(fileState(item))}</small></figcaption><button aria-label="Odebrat ${escapeHtml(item.file.name)}" data-live-remove-judge-file="${escapeHtml(item.id)}" ${['processing','uploading'].includes(item.status)?'disabled':''} type="button">×</button></figure>`).join('')}
