  async function hydrateMedia(root=bodyRoot()){for(const slot of root?.querySelectorAll('[data-live-car-photo]')||[]){const path=slot.dataset.liveCarPhoto,url=await mediaUrl(path);if(slot.isConnected&&url)slot.outerHTML=`<img alt="${escapeHtml(slot.dataset.liveCarAlt||'Registrované auto')}" src="${url}">`}}

  function navState(){const active=!!payload?.event?.liveEnabled,copy=active?`United ${payload.event.year} · aktivní`:loadState==='error'?'Stav nedostupný':payload?.event?'Nyní neaktivní':'Načítám stav…';document.querySelectorAll('[data-portal-target="live"]').forEach(button=>{button.classList.toggle('is-live',active);button.classList.toggle('is-error',loadState==='error');button.title=active?'Spustit organizační režim aktivního UNITED LIVE':'Otevřít organizační režim UNITED LIVE'});document.querySelectorAll('[data-admin-live-nav-copy]').forEach(node=>node.textContent=copy)}
