  function showEntry(opener=document.activeElement){entryOpener=opener;const dialog=entryDialog();if(!dialog)return;dialog.hidden=false;requestAnimationFrame(()=>dialog.querySelector('[data-admin-live-entry-confirm]:not([hidden]),[data-admin-live-entry-retry]:not([hidden]),[data-admin-live-entry-cancel]')?.focus())}
  function closeEntry({restore=true}={}){const dialog=entryDialog();if(dialog)dialog.hidden=true;if(restore)entryOpener?.focus?.({preventScroll:true});entryOpener=null}
