  function connection(offline=false){const dot=document.querySelector('[data-admin-live-connection]');if(!dot)return;dot.dataset.state=offline?'offline':'online';dot.title=offline?'Spojení kolísá, zobrazuji poslední potvrzený stav.':'Online · živý stav';dot.setAttribute('aria-label',dot.title)}
  function context(){const copy=document.querySelector('[data-admin-live-event]');if(copy)copy.textContent=payload?.event?`United ${payload.event.year} · organizátor`:'Vybraný ročník'}
