  function toggleMore(force){const menu=document.querySelector('[data-admin-live-more-menu]'),button=document.querySelector('[data-admin-live-more-toggle]');if(!menu||!button)return;const open=force??menu.hidden;menu.hidden=!open;button.setAttribute('aria-expanded',String(open));if(open)menu.querySelector('button')?.focus({preventScroll:true})}
