  function visibleMembers(){if(discipline==='show_shine')return memberResults;return memberResults.filter(member=>memberFilter==='registered'||memberFilter==='present'&&member.present||memberFilter==='absent'&&!member.present||memberFilter==='competition'&&member.competitionEntries>0||memberFilter==='all').sort((a,b)=>Number((b.cars||[]).some(car=>car.body===selectedCategory))-Number((a.cars||[]).some(car=>car.body===selectedCategory)))}
  function memberPhoto(member,car){const path=memberMediaPath(member,car);return path?`<span class="admin-live-member-photo" data-live-car-photo="${escapeHtml(path)}" data-live-car-alt="${escapeHtml(car.nickname||car.model||'Registrované auto')}"></span>`:'<span class="admin-live-member-photo"><b>E36</b></span>'}
  function membersRows(){if(memberStatus==='loading')return '<p role="status">Načítám účastníky…</p>';if(memberStatus==='error')return '<p role="alert">'+escapeHtml(memberError)+'</p><button data-live-choose-member type="button">Zkusit znovu</button>';const rows=visibleMembers();return rows.length?rows.map(member=>{const car=(member.cars||[]).find(item=>String(item.id)===String(member.registeredCarId))||member.cars?.[0]||null;return `<article class="admin-live-member-row" data-live-member="${escapeHtml(participantKey(member))}">${memberPhoto(member,car)}<button data-live-select-member="${escapeHtml(participantKey(member))}" type="button"><strong>${escapeHtml(member.nickname||member.name)}</strong><span>${escapeHtml(car?.nickname||car?.model||'Bez auta')}${car?.body?' · '+escapeHtml(car.body):''}</span><small>${member.present?'Dorazil':'Příjezd nepotvrzen'}${member.competitionEntries?` · ${member.competitionEntries}× soutěž`:''}</small></button></article>`}).join(''):'<p class="admin-live-status">'+(memberQuery?'Pro tento dotaz nebyl nalezen účastník.':'Zatím nejsou dostupní účastníci.')+'</p>'}
  function memberPickerView(){return `<section class="admin-live-picker"><form class="admin-live-search" data-live-member-search><input name="q" value="${escapeHtml(memberQuery)}" aria-label="Hledat účastníka" placeholder="Jméno, auto, SPZ nebo členský kód…"><button type="submit">Hledat</button></form><button class="admin-live-inline" data-live-new-car type="button">＋ Přidat jiné soutěžní auto</button><div class="admin-live-members" data-live-member-results>${membersRows()}</div>${memberHasMore?'<button data-live-more-members type="button">Načíst další</button>':''}</section>`}
  function membersView(){return '<h2>Vybrat účastníka</h2><button data-live-overview type="button">← Zpět k hodnocení</button>'+(newCarOpen||selectedMember()?selectedCard():memberPickerView())}
