  function canEditJudge(entry){if(savedJudge(entry.id||entry.entryId).submitted)return !!payload?.event?.liveEnabled&&loadState==='loaded';return !!entry.presentedAt&&!entry.votingClosed&&!!payload?.event?.liveEnabled&&loadState==='loaded'&&!['closed','published'].includes(currentState('show_shine').status)&&payload?.categories?.find(item=>item.category===entry.category)?.status!=='closed'}
