  function exhaustWorkflowView(){const state=currentState(),current=state.entry,showCategories=discipline==='show_shine'&&!selectedCategory;return `<section class="admin-live-section"><header class="admin-live-work-head"><div><span>SHOW &amp; SHINE${selectedCategory?' · '+escapeHtml(selectedCategory):''}</span><h2 tabindex="-1">${showCategories?'Vybrat kategorii.':'Hodnocení auta.'}</h2></div><nav aria-label="Vedlejší pohledy"><button class="admin-live-inline" data-live-subview="results" type="button">Výsledky</button></nav></header>${disciplineSwitch()}${activeCompetition()}${competitionControls()}${current&&discipline==='show_shine'&&!current.category?'<p class="admin-live-status">Aktuální auto zatím nemá kategorii. Vyber kategorii a účastníka, potom potvrď stejné auto tlačítkem Spustit hodnocení. Dosavadní známky zůstanou zachované.</p>':''}${showCategories?categoryOverview():participantStep()+selectedCard()}${current&&discipline==='show_shine'&&selectedCategory===current.category?judgeForm(current):''}</section>`}
